+        GATEWAY_COMMAND_SET_LEVEL, -1.0, 0U, &plan) == GATEWAY_COMMAND_PLAN_INVALID);
+    assert(gateway_command_policy_plan(
+        GATEWAY_COMMAND_SET_LEVEL, 101.0, 0U, &plan) == GATEWAY_COMMAND_PLAN_INVALID);
+    assert(gateway_command_policy_plan(
